#include <bits/stdc++.h>
using namespace std;
#define ll long long 

ll solve(ll a, ll b, ll n, vector <ll> &pre) {
    ll one = 3 * n - 2 * a - b;
    ll two = a + 2  *b;
    ll temp1 = 3LL * pre[one];
    ll temp2 = 2LL * pre[a];
    ll temp3 = pre[two];
    return temp1 + temp2 + temp3;
}

int main() {
    ll t;
    cin >> t;
    while (t--) {
        ll n;
        cin >> n;
        vector <ll> arr(3 * n);
        for (auto &i : arr) cin >> i;
        sort(arr.begin(), arr.end(), greater <ll>());
        vector <ll> pre(3 * n + 1, 0);
        for (int i  = 0;i < 3 * n;i++) {
            pre[i + 1] = pre[i] + arr[i];
        }
        ll res = 0;
        for (int i = 0;i <= n;i++) {
            ll low = 0, high = n - i;
            while (low < high) {
                ll mid = (low + high) >> 1;
                if (solve(i, mid, n, pre) <= solve(i, mid + 1, n, pre)) {
                    low = mid + 1;
                } else {
                    high = mid;
                }
            }
            res = max(res, solve(i, low, n, pre));
        }
        cout << res << endl;
    }
}
